mapper.select:
SELECT DISTINCT a.id id, a.object_name objectName, a.category_code categoryCode, a.category_name categoryName, a.maintenance_time maintenanceTime, a.maintenance_finish_time maintenanceFinishTime, a.maintenance_task_status maintenanceTaskStatus, a.maintenance_task_person maintenanceTaskPerson, b.maintenance_plan_name maintenancePlanName, b.responsibility_type responsibilityType, b.receive_dept_id receiveDeptId, b.receive_post_id receivePostId, b.responsibility_person_id responsibilityPersonId FROM maintenance_tasks a LEFT JOIN maintenance_plan b ON a.plan_id = b.id
and a.maintenance_time between #{param.releaseStartTime} and #{param.releaseEndTime}
and a.maintenance_finish_time between #{param.finishStartTime} and #{param.finishEndTime}
and a.object_name LIKE CONCAT('%',#{param.objectName},'%')
and a.category_code LIKE CONCAT('%',#{param.categoryCode},'%')
and a.maintenance_task_status = #{param.maintenanceTaskStatus}
ORDER BY a.maintenance_time DESC

SELECT DISTINCT a.id id, a.object_name objectName, a.category_code categoryCode, a.category_name categoryName, a.maintenance_time maintenanceTime, a.maintenance_finish_time maintenanceFinishTime, a.maintenance_task_status maintenanceTaskStatus, a.maintenance_task_person maintenanceTaskPerson, b.maintenance_plan_name maintenancePlanName, b.responsibility_type responsibilityType, b.receive_dept_id receiveDeptId, b.receive_post_id receivePostId, b.responsibility_person_id responsibilityPersonId FROM maintenance_tasks a LEFT JOIN maintenance_plan b ON a.plan_id = b.id LEFT JOIN maintenance_object c on c.plan_id = b.id
and a.maintenance_time between #{param.releaseStartTime} and #{param.releaseEndTime}
and a.maintenance_finish_time between #{param.finishStartTime} and #{param.finishEndTime}
and a.object_name LIKE CONCAT('%',#{param.objectName},'%')
and a.category_code = #{param.categoryCode}
and a.maintenance_task_status = #{param.maintenanceTaskStatus}
and c.key_id = #{param.keyId}
and (b.responsibility_person_id like CONCAT('%',#{param.userId},'%') or b.receive_dept_id like CONCAT('%',#{param.organization},'%') or b.receive_post_id like CONCAT('%',#{param.position},'%'))

select object_id as deviceId, count(id) as num, max(maintenance_finish_time) last_time from maintenance_tasks
maintenance_finish_time is not null
and object_id in
#{id}
and create_time between #{param.period.begin} and #{param.period.end}
group by object_id
